// Package webadmin embeds the admin dashboard's static assets. app.css is
// generated by Tailwind (`make css`) and committed so `go build` needs no
// Node toolchain.
package webadmin

import (
	"crypto/sha256"
	"embed"
	"encoding/hex"
	"io/fs"
)

//go:embed static
var staticFS embed.FS

// Static returns the dashboard's static files rooted at the static directory.
func Static() fs.FS {
	sub, err := fs.Sub(staticFS, "static")
	if err != nil {
		panic(err)
	}
	return sub
}

// AssetVersion is a short content hash of the static files, appended to asset
// URLs so browsers pick up a new stylesheet after an upgrade.
var AssetVersion = func() string {
	h := sha256.New()
	_ = fs.WalkDir(staticFS, "static", func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return err
		}
		b, err := staticFS.ReadFile(path)
		if err != nil {
			return err
		}
		h.Write([]byte(path))
		h.Write(b)
		return nil
	})
	return hex.EncodeToString(h.Sum(nil))[:10]
}()
